import {renderInbox,installInboxHandlers} from '../shared/decision-inbox.mjs?v=20261102-expert1';
import {groupProductionRows,productionCurvePanels} from './production-curves.mjs?v=20261102-fluids1';
import {esc,num,panel,chart,table,flow,field,download,downloadRows,readFile} from './ui.mjs';
import {avg,balance,layerSplit,lagCorrelation,allocate,measureEffect,reserves,evolve,mpc,differenceInDifferences,toolEvidence} from './engine.mjs';
import {renderStudio,studioAction,studioUpload,studioSelection,currentExperiment} from './studio.mjs?v=20261101-eval1';
import {DATASETS,PAGE_MAP,METHOD_CARDS} from './catalog.mjs';
import {api} from './training.mjs?v=20261101-eval1';
const nav=[['monitoring-inbox','⇢','监测研判收件箱'],['overview','◈','生产决策总览'],['connectivity','⌘','井间连通性'],['layers','▤','分层注采劈分'],['control','⇄','注采调控方案'],['measures','◎','措施推荐与评价'],['evolution','∿','油藏时序演化'],['reserves','▥','储量偏差管理'],['studio','◇','模型训练工作台'],['copilot','✧','大模型分析助手'],['sources','▦','数据与技术依据']];
const state={page:location.hash.slice(1)||'overview',source:'production',well:'all',remote:{url:'',token:''},report:'',service:'未连接',data:{},results:{},messages:[],lastReport:null};
let toastTimer;
const formCache=new Map();let formScope=null;
function captureForms(){if(!formScope)return;const values={};for(const el of document.querySelectorAll("main input[type=number],main select,main textarea"))if(el.id&&!el.dataset.studioChange)values[el.id]=el.value;formCache.set(formScope,values);}
function restoreForms(){formScope=state.page+(state.page==='studio'?'/'+currentExperiment().model.id:'');for(const [id,v] of Object.entries(formCache.get(formScope)??{})){const el=document.getElementById(id);if(el&&(!el.options||[...el.options].some(o=>o.value===v)))el.value=v;}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',5000);}
const val=(id,fallback=0)=>{const e=document.getElementById(id);const v=e?Number(e.value):fallback;if(!Number.isFinite(v)||e?.value==='')throw Error('请输入有效参数：'+id);return v;};
const selectedRows=()=>state.well==='all'?state.data.active:state.data.active.filter(r=>r.well_id===state.well);
const grouped=groupProductionRows;
function clearScopeResults(){state.results={};state.resultContext={};state.report='';state.lastReport=null;}
function getSummary(){const rs=grouped(selectedRows()),last=rs.at(-1),previous=rs.slice(-15,-1);return {rs,last,oil:avg(rs.slice(-7).map(r=>r.oil)),water:avg(rs.slice(-7).map(r=>r.water_cut)),pressure:avg(rs.slice(-7).map(r=>r.pressure)),change:previous.length?(last.oil-avg(previous.map(r=>r.oil)))/Math.max(.01,avg(previous.map(r=>r.oil)))*100:0};}
const sourceBadge=()=>`<span class="source-chip ${state.source==='volve'?'real':''}">${state.source==='volve'?'Volve公开实测抽样':state.source==='upload'?'用户上传数据':'合成井组场景'}</span>`;
function noteSource(){return `<div class="note ${state.source==='volve'?'green':''}">${sourceBadge()}　${state.source==='production'?'当前井组、井位和调控响应均为可复现合成场景，用于验证工作流。':state.source==='volve'?'Volve日期与观测保留；不同井可能来自不同连续日段。油田总注水量不用于逐井连通性反演。':'上传数据只在当前浏览器会话处理；请按字段字典核实单位、体积基准和数据质量。'} 模型效果请在训练工作台使用独立测试集评价。</div>`;}
function kpi(title,value,unit,note){return `<article class="kpi"><label>${title}<span style="color:#b18f57">↗</span></label><strong>${num(value)}<small>${unit}</small></strong><p>${note}</p></article>`;}
function render(){captureForms();if(!nav.some(n=>n[0]===state.page))state.page='overview';const selected=nav.find(n=>n[0]===state.page);document.getElementById('app').innerHTML=`<div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brandmark"><img src="../agent/assets/cnpc-logo.png" alt="中国石油标识"></div><div><strong>ChinaOil</strong><small>RESERVOIR INTELLIGENCE</small></div></div><div class="space-label">智能生产 · 分析与决策</div><nav class="nav" aria-label="主要功能">${nav.map(([id,icon,n])=>`<button data-nav="${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${n}${id==='copilot'?'<b>AI</b>':''}</button>`).join('')}</nav><div class="side-foot"><span class="dot"></span>浏览器计算引擎就绪<a href="../agent/">↗ 油藏生产态势感知智能体</a><a href="../">↗ 智慧油藏协同平台</a><a href="https://github.com/oilreservior123/ChinaOil-platform/tree/main/dist/decision" target="_blank" rel="noopener">GitHub · 开源与部署</a><div style="padding-top:10px">依据研究PPT第32–47页<br>研究与流程验证版 · v1.0</div></div></aside><header class="topbar"><div class="row"><button class="mobile-nav" data-action="menu" aria-label="展开功能导航">☰</button><span class="crumb">智慧油藏 / 生产动态与决策 / <b>${selected[2]}</b></span></div><div class="right"><span class="tiny">数据 → 模型 → 证据 → 预案</span><button data-nav="copilot" class="tag ${state.service==='已连接'?'green':'gray'}">大模型${state.service}</button><div class="avatar" aria-label="研究工作台">CN</div></div></header><main class="main"><div class="head"><div><div class="eyebrow">INTELLIGENT PRODUCTION & DECISION</div><h1>${state.page==='overview'?'油藏智能生产动态分析与决策':selected[2]}</h1><p>${pageDescription(state.page)}</p></div><div class="row">${state.page==='monitoring-inbox'?'<span class="tag">本地监测交接 · 以各包来源为准</span>':sourceBadge()+'<button class="btn" data-action="report">↓ 导出分析报告</button>'}</div></div>${views[state.page]()}${state.lastCalculation?`<div class="unit-note">最近一次数值工具计算耗时：${num(state.lastCalculation.seconds,4)}秒。数值工具不涉及参数训练时，不显示虚构训练轮次。</div>`:''}<footer><span>ChinaOil · 大模型驱动的油藏智能生产动态分析与决策平台</span><span>PPT 32–47 · 每项结论可追溯</span></footer></main></div>`;restoreForms();}
function pageDescription(page){return {'monitoring-inbox':'接收态势感知智能体的监测证据、模型区间与待审核措施；同浏览器本地交接，可通过JSON跨设备导入。',overview:'依托动态演化规律与模型工具，贯通生产研判、趋势预测、措施设计与闭环评价。',connectivity:'动态注采响应与静态认识相互验证，量化响应时滞及连通候选关系。',layers:'以小层属性与连通强度为基础，结合实测剖面校准分层贡献。',control:'以压力、注采平衡和地面能力为约束，生成可复核的井组调控预案。',measures:'从异常诊断到治理措施，跟踪1周、1月、3月和6月的实际效果。',evolution:'按时间戳管理阶段物性，支持当前阶段方案设计与演化情景比较。',reserves:'比较递减预测、经济极限与实际生产偏差，管理调整情景。',studio:'配套数据、模型公式、结构、参数、独立评价与实测训练时长。',copilot:'通过证据检索与数值工具形成结构化研判，连接服务后启用大模型推理。',sources:'明确PPT业务覆盖、样本来源、计算口径与各类模型能力边界。'}[page];}
const views={'monitoring-inbox':renderInbox,overview,connectivity,layers,control,measures,evolution,reserves:reservesView,studio:renderStudio,copilot,sources};
function overview(){const {rs,last,oil,water,pressure,change}=getSummary(),history=rs.slice(-90),labels=history.map(r=>r.date),wells=[...new Set(state.data.active.map(r=>r.well_id))];return `<section class="hero"><div><span class="section-label">RESERVOIR OPERATIONS / DECISION WORKSPACE</span><h2>读懂生产变化，让每一次调控有据可依</h2><p>汇聚生产、注采、剖面与阶段物性，形成“识别问题—分析原因—预测响应—优化措施—跟踪反馈”的完整工作链。</p><div class="row" style="margin-top:14px"><button class="btn primary" data-nav="copilot">✧ 生成动态研判</button><button class="btn" data-nav="studio">进入模型工作台 →</button></div></div><div class="emblem">AI</div></section><div class="toolbar"><div class="row"><label>资料来源 <select id="global-source"><option value="production" ${state.source==='production'?'selected':''}>合成井组 · 同期注采场景</option><option value="volve" ${state.source==='volve'?'selected':''}>Volve · 公开实测抽样</option>${state.source==='upload'?'<option value="upload" selected>用户上传</option>':''}</select></label><label>分析对象 <select id="global-well"><option value="all">全部井（按日期汇总）</option>${wells.map(w=>`<option ${state.well===w?'selected':''}>${esc(w)}</option>`).join('')}</select></label></div><label class="btn">↑ 导入生产CSV<input id="global-upload" type="file" accept=".csv,.json" hidden></label></div>${noteSource()}<div class="kpis">${kpi('近7个观测日产油',oil,'标准立方米/日','当前所选对象 · 按日期汇总')}${kpi('近7个观测含水率',water,'%','按产水 / 产液计算')}${kpi('近7个观测井下压力',pressure,'兆帕','井下压力不自动等于地层静压')}${kpi('最新日产油相对前14期',change,'%','变化提示，不直接等于异常诊断')}</div><div class="page-grid">${panel('生产趋势与变化',chart([{name:'实测/场景产油',values:history.map(r=>r.oil),labels,color:'#ab2935'},{name:'7期滚动基线',values:history.map((r,i)=>avg(history.slice(Math.max(0,i-6),i+1).map(r=>r.oil))),color:'#b58e51',dash:true}],{unit:'标准立方米/日'}),'<button class="btn text" data-nav="studio">训练预测模型 →</button>','曲线为观测与滚动统计基线；未来预测需在工作台拟合并评价模型。')}${panel('井组注采响应视图',network(),'<span class="tag">示意井位</span>','示意节点和连线仅表达工作流。连通性数值请在专页计算，不将示意线作为地质证据。')}</div>${productionCurvePanels(history)}<div class="grid equal gap">${panel('压力动态',chart([{name:'井下压力',values:history.map(r=>r.pressure),labels,color:'#4b81aa'}],{unit:'兆帕'}))}${panel('含水率动态',chart([{name:'含水率',values:history.map(r=>r.water_cut),labels,color:'#318571'}],{unit:'%'}))}</div><div class="grid equal gap">${panel('分析与决策工作流',flow(['动态数据质检','异常/趋势分析','连通与劈分','约束调控','效果反馈'])+'<div class="note">候选根因需要示踪剂、试井、剖面或现场确认资料交叉验证；预测相关性不能单独证明调控因果效果。</div>')}${panel('预警颜色与处置含义',warningLegend())}</div>`;}
function warningLegend(){return `<div class="card-stack">${[['#ac2834','红色 · 严重候选异常','复核压力、产量或设备约束，人工确认后处置'],['#bc8f35','黄色 · 变化关注','持续跟踪指标漂移，补充诊断证据'],['#4a80aa','蓝色 · 信息提示','资料待补、模型更新或分析提示'],['#30806a','绿色 · 当前检查通过','仅代表当前检查项满足条件'],['#909395','灰色 · 尚未评价','没有充分数据或尚未运行模型']].map(([c,n,t])=>`<div><span style="color:${c}">●</span> <b>${n}</b><div class="tiny" style="margin-left:18px">${t}</div></div>`).join('')}</div>`;}
function network(){return `<div class="well-map"><svg viewBox="0 0 500 280" role="img" aria-label="井组注采流程示意，非真实井位"><defs><pattern id="grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" fill="none" stroke="#ffffff08"/></pattern></defs><rect width="500" height="280" fill="url(#grid)"/>${[[105,90,270,55,.7],[105,90,365,140,.4],[105,90,245,222,.3],[95,214,270,55,.3],[95,214,365,140,.6],[95,214,245,222,.8]].map(([x,y,a,b,c])=>`<line x1="${x}" y1="${y}" x2="${a}" y2="${b}" stroke="#b59561" stroke-width="${c*3}" opacity="${c}"/>`).join('')}${[[105,90,'注水井1','#699bc3'],[95,214,'注水井2','#699bc3'],[270,55,'生产井1','#c8a564'],[365,140,'生产井2','#c8a564'],[245,222,'生产井3','#c8a564']].map(([x,y,n,c])=>`<circle cx="${x}" cy="${y}" r="18" fill="${c}18" stroke="${c}55"/><circle cx="${x}" cy="${y}" r="5" fill="${c}"/><text x="${x+24}" y="${y+4}">${n}</text>`).join('')}<text x="20" y="25">注采方向 · 结构示意</text></svg><div class="network-legend"><span>● 蓝：注水节点</span><span style="color:#c8a564">● 金：生产节点</span><span>虚线：候选响应方向</span></div></div>`;}
function connectivity(){const result=state.results.connectivity;return `<div class="page-grid">${panel('注采响应互相关分析',`<div class="note">默认使用合成场景中同期的I-01/I-02与P-01/P-02/P-03；互相关只提供响应候选。先去趋势、排除共同操作与停井影响，再结合静态资料、示踪剂和干扰试井验证。</div><div class="tool-form"><label>注水井<select id="injector"><option>I-01</option><option>I-02</option></select></label><label>生产井<select id="producer"><option>P-01</option><option>P-02</option><option>P-03</option></select></label>${field('max-lag','最大滞后 / 天',20)}<label>预处理<select id="lag-preprocess"><option value="difference">一阶差分（建议）</option><option value="raw">原始量</option></select></label></div><button class="btn primary" data-action="connectivity">计算注采响应</button><label class="btn" style="margin-left:8px">↑ 上传同期配对CSV<input id="pair-upload" type="file" accept=".csv,.json" hidden></label><p class="tiny" style="margin-top:12px">上传字段：date、injection（注入量）、liquid（产液量）；每天一行，同一井对，至少8行。</p>${result?`<div class="metric-grid gap"><div><span>注入领先响应</span><b>${result.lag}天</b></div><div><span>互相关系数</span><b>${num(result.correlation,3)}</b></div><div><span>先验验证状态</span><b style="font-size:16px">待地质复核</b></div></div>${chart([{name:'互相关',values:result.curve.map(r=>r.correlation),labels:result.curve.map(r=>r.lag),color:'#ab2935'}],{unit:'相关系数，无量纲',label:'注入领先的滞后天数'})}`:'<div class="empty">选择井对后运行分析；不预填连通强度</div>'}`)}${panel('动静结合与CRM解释',`${network()}<div class="model-formula">CCF(ℓ)=corr(ΔIₜ, ΔQₜ₊ℓ)<br>τ dq/dt + q = Σᵢ fᵢIᵢ − τJ dpwf/dt</div><div class="note">ℓ：响应滞后天数；fᵢ：注采增益；τ：时间常数；J：采液指数。工作台CRM为恒井底流压、单输入集总版本；多井对反演需独立注水序列及可辨识性检验。</div><button class="btn" data-nav="studio">打开CRM / 随机森林模型 →</button>`,'<span class="tiny">PPT 35–37</span>')}</div><div class="gap">${panel('连通性分析所需证据',table([{type:'静态先验',data:'井位、砂体连通、断层、层位对比、渗透率',use:'约束可能的连通路径'},{type:'动态观测',data:'同期注采量、井底流压、示踪剂、干扰试井',use:'识别响应时滞与独立连通证据'},{type:'历史措施',data:'调剖、堵水及其响应',use:'验证优势通道和无效水循环候选'}],[['type','证据类型'],['data','需要的数据'],['use','作用']]))}</div>`;}
function layers(){const result=state.results.layers;return `<div class="page-grid">${panel('小层注入 / 产液贡献计算',`<div class="tool-form"><label>生产井<select id="layer-well">${[...new Set((state.data.uploadLayers??state.data.layers).map(r=>r.well_id))].map(w=>`<option>${esc(w)}</option>`).join('')}</select></label>${field('layer-total','总注入/产液 / 标准立方米·日⁻¹',600)}<label>用途<select id="layer-mode"><option value="injection">注入量劈分</option><option value="liquid">产液量劈分</option></select></label></div><button class="btn primary" data-action="layers">计算分层贡献</button><label class="btn" style="margin-left:8px">↑ 上传小层属性<input id="layers-upload" type="file" accept=".csv,.json" hidden></label><p class="tiny" style="margin-top:10px">上传字段：well_id、layer、permeability、thickness、connectivity；含水率water_cut可选。单位：毫达西、米、比例、%。</p>${result?`<div class="note green">已校验分层总量守恒：${num(result.reduce((s,r)=>s+r.volume,0))} 标准立方米/日</div>${table(result,[['layer','小层'],['fraction','比例'],['volume','分层量（标准立方米/日）'],['intensity','强度（标准立方米/日/米）'],['water_cut','含水率（%）'],['oilContribution','产液模式产油贡献（标准立方米/日）']])}${chart([{name:'分层量',values:result.map(r=>r.volume),labels:result.map(r=>r.layer),color:'#b58e51'}],{unit:'标准立方米/日',label:'小层'})}`:'<div class="empty">运行后展示分层比例、产液强度与总量校验</div>'}`)}${panel('模型结构、公式与更新规则',`${flow(['当前阶段物性','连通强度','分层权重','总量守恒'])}<div class="model-formula">Cₗ=kₗhₗf连通,ₗ<br>fₗ=Cₗ/ΣCⱼ；Qₗ=fₗQ总<br>产液强度=Q液,ₗ/h射孔,ₗ</div><div class="note">此页执行透明的能力权重基线。训练工作台另提供随机森林剖面监督模型。实际注水劈分还受层间压差、黏度和流度影响，不能仅凭kh判定真实吸水剖面。</div><p class="explanation">PPT重训条件：预测剖面与实测比例的偏差超过15%时，提示复核并用新的实测剖面重新训练。必须同时具备剖面观测与层位匹配。</p><button class="btn gap" data-nav="studio">训练剖面劈分模型 →</button>`,'<span class="tiny">PPT 38、40</span>')}</div><div class="gap">${panel('当前小层资料 · 合成场景',table(state.data.layers,[['well_id','井号'],['layer','层号'],['permeability','渗透率（毫达西）'],['thickness','厚度（米）'],['porosity','孔隙度'],['connectivity','连通强度'],['water_cut','含水率（%）']],30),'<a class="btn text" href="data/layers.csv" download>↓ 样本</a>')}</div>`;}
function control(){const r=state.results.control,m=state.results.mpc;return `<div class="page-grid">${panel('井组注采平衡评价',`<div class="tool-form">${field('balance-I','注水 / 标准立方米·日⁻¹',850)}${field('balance-O','产油 / 标准立方米·日⁻¹',400)}${field('balance-W','产水 / 标准立方米·日⁻¹',500)}${field('balance-Bo','原油体积系数',1.15,.01)}${field('balance-Bw','水体积系数',1.02,.01)}${field('balance-p','当前地层静压 / 兆帕',22,.1)}${field('balance-p0','原始地层压力 / 兆帕',25,.1)}${field('balance-trend','压力变化 / 兆帕·月⁻¹',-.2,.01)}</div><button class="btn primary" data-action="balance">评价平衡状态</button>${state.results.balance?`<div class="metric-grid gap"><div><span>地下体积注采比</span><b>${num(state.results.balance.ratio,3)}</b></div><div><span>压力保持水平</span><b>${num(state.results.balance.pressureRetention*100)}%</b></div><div><span>联合评价</span><b style="font-size:20px">${state.results.balance.state}</b></div></div>`:''}<div class="note">油水两相地下体积口径：I水B水/(q油B油+q水B水)。含游离气时需扩展。比值&lt;0.9且压力下降提示亏空；&gt;1.1且压力上升提示过量；其他组合待联合研判。</div>`,'<span class="tiny">PPT 39</span>')}${panel('分层配注与压力约束',`<div class="tool-form">${field('supply','总供水目标 / 标准立方米·日⁻¹',700)}${field('fracture-margin','破裂压力安全裕量 / 兆帕',1,.1)}</div><p class="explanation">按小层吸水能力、连通和能量补充权重分配，并逐层检查：p预计=p地层+Q/J≤p破裂−安全裕量。</p><div class="row gap"><button class="btn primary" data-action="allocate">生成配注方案</button><button class="btn" data-action="export-control" ${!r?'disabled':''}>↓ 配注结果</button></div>${r?table(r,[['id','井/层'],['target','目标配注（标准立方米/日）'],['capacity','可用容量'],['predictedPressure','预计注入压力（兆帕）']]):'<div class="empty">方案生成后显示各层配注与压力校验</div>'}<div class="note">本页使用合成小层吸水指数及压力，不将“注水量”与“破裂压力”直接比较。未使用量会保留，不为凑足目标而突破约束。</div>`)}</div><div class="grid equal gap">${panel('滚动调控 MPC · 压力响应情景',`<div class="tool-form">${field('mpc-current','当前压力 / 兆帕',22,.1)}${field('mpc-target','目标压力 / 兆帕',23,.1)}${field('mpc-liquid','地下采出液量 / 立方米·步⁻¹',700)}${field('mpc-max','最大注入 / 立方米·步⁻¹',1100)}${field('mpc-fracture','压力上限 / 兆帕',29,.1)}${field('mpc-gain','压力响应系数 α',.0003,.00001)}</div><button class="btn primary" data-action="mpc">搜索6步可行控制量</button>${m?`<div class="note green">首步推荐注入：${num(m.injection)} 立方米/步；此情景保持同一控制量6步。</div>${chart([{name:'压力响应情景',values:m.path,color:'#4a7eab'}],{unit:'兆帕',label:'调控步数'})}`:''}<p class="tiny">α单位：兆帕/立方米；每步对应用户定义的统一周期。当前为简化储集系数模型，需现场标定。</p>`) }${panel('产液结构优化 · Pareto方案',`<p class="explanation">在总处理能力与各层产液边界内，比较两层产液分配的产油量和产水量。产油=Q液(1−含水率)，不把单纯重新分配当作已验证增油效果。</p><div class="tool-form">${field('handling','总处理能力 / 标准立方米·日⁻¹',600)}${field('wc-low','低含水层含水率 / %',30)}${field('wc-high','高含水层含水率 / %',80)}${field('layer-cap','单层产液上限 / 标准立方米·日⁻¹',400)}</div><button class="btn primary" data-action="pareto">运行NSGA-II方案搜索</button>${state.results.pareto?table(state.results.pareto,[['q1','低含水层产液'],['q2','高含水层产液'],['oil','总产油'],['water','总产水']]):'<div class="empty">运行后展示非支配前沿方案</div>'}<div class="note">PPT约束：井设备上限、最小经济产液量、总液处理能力及含水目标。当前两层研究版：种群50、迭代40代、随机种子42、产液下限0；现场需补充经济下限及经验证的响应代理模型。</div>`)}</div>`;}
function measures(){const r=state.results.measures;return `<div class="page-grid">${panel('异常—根因—措施知识链',`<div class="tool-form"><label>异常线索<select id="anomaly">${state.data.knowledge.map(k=>`<option value="${k.id}">${k.anomaly}</option>`).join('')}</select></label></div><button class="btn primary" data-action="recommend">检索治理措施</button>${state.results.recommend?`<div class="report-card"><h3>${esc(state.results.recommend.cause)}</h3><p class="report">建议：${esc(state.results.recommend.measure)}\n适用条件：${esc(state.results.recommend.condition)}\n依据：${esc(state.results.recommend.evidence)}\n历史成功率：未提供现场样本，暂不排序为“最优”。</p></div>`:'<div class="empty">选择异常线索，查看候选措施与适用条件</div>'}${flow(['异常类型','候选根因','治理措施','适用条件','实际效果'])}<div class="note">知识边的诊断置信度和措施成功率应由真实诊断与历史措施统计标定；内置知识库不编造概率。</div>`,'<span class="tiny">PPT 32–33、42</span>')}${panel('措施增油与投入产出评价',`<div class="tool-form"><label>跟踪节点<select id="follow-days"><option value="7">第1周</option><option value="30">第1个月</option><option value="90">第3个月</option><option value="180">第6个月</option></select></label>${field('measure-cost','措施投入 / 元',100000)}${field('oil-margin','每单位增油净收益 / 元·标准立方米⁻¹',1800)}</div><div class="row"><button class="btn primary" data-action="measure-effect">计算节点效果</button><label class="btn">↑ 上传实际/基线<input id="follow-upload" type="file" accept=".csv,.json" hidden></label></div><p class="tiny" style="margin-top:10px">字段：date、oil、baseline，日级，单位均为标准立方米/日。基线需独立估计；不能用措施后真实值拟合反事实。</p>${r?`<div class="metric-grid gap"><div><span>累计增油 / 标准立方米</span><b>${num(r.incremental)}</b></div><div><span>净收益 / 元</span><b>${num(r.net,0)}</b></div><div><span>净投入收益率</span><b>${num(r.roi===null?null:r.roi*100)}%</b></div></div><div class="note">当前来源：${esc(state.data.followOrigin??'合成措施跟踪与已知无措施基线')}。${r.days}个日级观测；不构成现场因果增油证明。</div>`:''}`)}</div><div class="gap">${panel('措施执行与效果闭环',`<div class="timeline">${[['1周','判断是否见效，比较产液/注入变化'],['1个月','累计增油、增注量与预期比较'],['3个月','评估有效期与配套措施'],['6个月','综合效果、投入产出与模型反馈']].map(([n,t])=>`<div><strong>${n}</strong><small>${t}</small></div>`).join('')}</div><div class="tool-form">${field('expected-effect','预期平均增油 / 标准立方米·日⁻¹',20,.1)}${field('actual-effect','实际平均增油 / 标准立方米·日⁻¹',13,.1)}${field('bias-periods','连续偏差节点数',2)}</div><button class="btn" data-action="effect-bias">核对25%偏差触发条件</button>${state.results.bias?`<div class="note">${esc(state.results.bias)}</div>`:''}<div class="gap"><h3>措施对照评价 · 双重差分</h3><div class="tool-form">${field('did-t0','措施组前期均值',100)}${field('did-t1','措施组后期均值',130)}${field('did-c0','对照组前期均值',80)}${field('did-c1','对照组后期均值',90)}</div><button class="btn" data-action="did">计算双重差分</button>${state.results.did!==undefined?`<div class="note">差分估计：${num(state.results.did)}标准立方米/日；输入默认值为教学场景。需要平行趋势、无同期干预等假设成立，才能解释为措施效应。</div>`:''}<p class="tiny">四项均值单位：标准立方米/日。训练耗时不适用；此处为解析计算，不自动验证因果假设。</p></div><p class="tiny">反馈只生成模型重训任务提示；经人工核验的新增标签再纳入训练，不自动回流独立测试集。</p>`)}</div>`;}
function evolution(){const r=state.results.evolution;return `<div class="page-grid">${panel('当前阶段物性演化情景',`<div class="note">PPT45–47页所列方向作为研究假设，需按油藏与阶段检验。此页经验系数可复核，不将所有油藏都视为同一变化规律。</div><div class="tool-form">${field('evo-k','初始渗透率 / 毫达西',300)}${field('evo-phi','初始孔隙度 / 小数',.2,.001)}${field('evo-mu','初始黏度 / 毫帕·秒',3,.1)}${field('evo-E','累计水洗暴露指数 E',4,.1)}</div><button class="btn primary" data-action="evolve">计算阶段情景</button>${r?`<div class="metric-grid gap"><div><span>当前渗透率 / 毫达西</span><b>${num(r.permeability)}</b></div><div><span>当前孔隙度</span><b>${num(r.porosity,4)}</b></div><div><span>当前黏度 / 毫帕·秒</span><b>${num(r.viscosity,3)}</b></div></div>${chart([{name:'场景渗透率',values:r.curve.map(v=>v.permeability),labels:r.curve.map((v,i)=>(i/2).toFixed(1)),color:'#b58e51'}],{unit:'毫达西',label:'累计水洗暴露指数E'})}`:''}`)}${panel('六类参数与方案关联',table([{n:'孔渗与孔喉结构',u:'重复岩心、测井、注入能力',use:'产能、波及与连通修正'},{n:'润湿性',u:'润湿角、岩心驱替',use:'残余油与驱替效率'},{n:'相渗曲线',u:'阶段相渗试验、动态反演',use:'含水与油水分流预测'},{n:'流体性质',u:'PVT、黏度、组分',use:'流动与经济极限'},{n:'岩石力学 / 地应力',u:'当前应力场、力学试验',use:'压裂设计与井壁稳定'},{n:'储层伤害',u:'水质、结垢、堵塞与敏感性',use:'注入能力与解堵措施'}],[['n','参数类别'],['u','需要的观测'],['use','关联决策']]),'<span class="tiny">PPT 45–47</span>')}</div><div class="gap">${panel('带时间戳的阶段物性库',table(state.data.evolution,[['date','采样时间'],['well_id','井号'],['permeability','渗透率（毫达西）'],['porosity','孔隙度'],['viscosity','黏度（毫帕·秒）'],['residualOil','残余油饱和度']],15),'<a class="btn text" href="data/evolution.csv" download>↓ 合成参数样例</a>','物性、相渗、应力与伤害参数应保留采样时间、解释版本和适用阶段，不能自动套用初期参数。')}</div>`;}
function reservesView(){const r=state.results.reserves;return `<div class="note red">储量研究与偏差分析模块。计算结果是给定递减与经济假设下的可采体积情景，不是经认证的SEC储量报告，也不保证储量增长或替补率达标。</div><div class="page-grid">${panel('递减与经济极限情景',`<div class="tool-form">${field('reserve-qi','起始产油 / 标准立方米·日⁻¹',100)}${field('reserve-D','初始递减率 / 日⁻¹',.001,.0001)}${field('reserve-b','双曲指数 b（0–1）',.4,.1)}${field('reserve-years','预测期限 / 年',5)}${field('reserve-price','油价 / 元·标准立方米⁻¹',3000)}${field('reserve-water-cost','产水成本 / 元·标准立方米⁻¹',30)}${field('reserve-fixed','固定日成本 / 元·日⁻¹',5000)}${field('reserve-wc','含水率 / %',60)}${field('reserve-base','对比基准体积 / 标准立方米',120000)}</div><button class="btn primary" data-action="reserves">计算情景与偏差</button>${r?`<div class="metric-grid gap"><div><span>预测期经济可采体积</span><b>${num(r.volume,0)}</b></div><div><span>经济有效期 / 天</span><b>${r.effectiveDays}</b></div><div><span>相对基准偏差</span><b>${num(r.deviation)}%</b></div></div>${chart([{name:'经济有效期内产油情景',values:r.curve.filter((_,i)=>i%10===0).map(v=>v.oil),labels:r.curve.filter((_,i)=>i%10===0).map(v=>v.day),color:'#aa2834'}],{unit:'标准立方米/日',label:'起算后的天数'})}`:''}`)}${panel('点—线—面偏差管理',`${flow(['单井预测偏差','井组趋势汇总','区块情景调整'])}<div class="model-formula">q(t)=qᵢ/(1+bDᵢt)¹⁄ᵇ<br>净现金流=q油P油−q水C水−C固定<br>偏差=(情景体积−基准体积)/基准体积</div><div class="card-stack gap"><div class="scenario"><h3>产量不达预期</h3><p class="tiny">复核计量、开井制度和措施效果，按当前阶段重拟合递减。</p></div><div class="scenario"><h3>递减加快 / 经济极限提前</h3><p class="tiny">检查物性时变、含水和成本变化，比较调控或治理情景。</p></div><div class="scenario"><h3>储量替补目标</h3><p class="tiny">≥100%作为PPT管理目标展示；需有符合适用规则的新增与采出储量台账，当前样例不计算认证替补率。</p></div></div><div class="note">当前按恒定含水率、恒定价格与成本、无折现计算。年度价格口径、权益、项目成熟度与储量分类须由合格专业人员另行评估。</div>`,'<span class="tiny">PPT 43–44</span>')}</div>`;}
function copilot(){return `<div class="page-grid">${panel('生产动态分析助手',`<div class="row"><span class="tag ${state.service==='已连接'?'green':'gray'}">${state.service==='已连接'?'远程大模型可用':'本地证据模板模式'}</span><span class="tiny">检索知识 → 调用模型 → 组织证据 → 生成预案</span></div><div class="quick"><button data-prompt="分析当前产油、含水和压力变化，列出待验证原因">分析当前生产变化</button><button data-prompt="针对能量亏空生成注采调控预案和跟踪计划">生成注采调控预案</button><button data-prompt="推荐高含水井治理措施，说明适用条件与证据缺口">推荐高含水治理措施</button></div><label class="tiny" for="question">输入分析目标</label><textarea id="question" class="copilot-input" placeholder="例如：分析当前井组的产量下降原因，给出有约束的调控建议及1、3、6个月跟踪指标。">${esc(state.question??'分析当前生产变化，生成可复核的动态研判与调控预案。')}</textarea><div class="row" style="margin-top:13px"><button class="btn primary" data-action="ask" ${state.asking?'disabled':''}>${state.asking?'正在检索与分析…':'✧ 生成分析与预案'}</button><button class="btn" data-action="export-ai" ${!state.report?'disabled':''}>↓ 导出预案</button><label class="tiny"><input type="checkbox" id="send-evidence" ${state.sendEvidence?'checked':''}> 允许本次将汇总指标和工具结果发送到已配置服务</label></div>${state.report?`<div class="report-card"><div class="source-title"><span class="tag ${state.reportMode==='llm'?'green':''}">${state.reportMode==='llm'?'大模型生成 · 请复核证据':'本地规则与证据模板 · 未调用大模型'}</span></div><div class="report">${esc(state.report)}</div></div>`:'<div class="empty">提出问题后，先形成生产证据和数值工具摘要，再输出候选原因、调控步骤和跟踪计划。</div>'}`)}${panel('大模型与计算服务配置',`<div class="note">GitHub Pages承载网页和浏览器模型。大模型密钥保留在独立服务端，前端只填写服务地址和访问令牌；令牌仅保存在本次会话内存。</div><label class="input-label">HTTPS服务地址<input style="width:100%" id="service-url" placeholder="https://your-service.example" value="${esc(state.remote.url)}"></label><label class="input-label gap">服务访问令牌<input style="width:100%" id="service-token" type="password" autocomplete="off" placeholder="服务器配置的 DECISION_ACCESS_TOKEN"></label><button class="btn primary gap" data-action="connect">测试并连接服务</button><div class="status">状态：${state.service}</div><p class="tiny">接口：POST /health、/chat、/train、/predict。/train启用真实XGBoost需在服务端安装xgboost。连接模型名称由服务端配置，不在页面伪装预设模型。</p><a class="btn gap" href="https://github.com/oilreservior123/ChinaOil-platform/blob/main/backend/decision_README.md" target="_blank" rel="noopener">计算服务部署说明 ↗</a><div class="gap">${flow(['生产指标','PPT知识条目','已运行工具结果','模型回复'])}</div><div class="note">大模型用于证据解释与方案组织。具体配注、增油和经济结果以数值计算为依据；缺少参数时应明确标记待补充。</div>`)}</div>`;}
function sources(){return `${panel('PPT第32–47页业务覆盖',table(PAGE_MAP.map(([page,module,content])=>({page,module,content})),[['page','页码'],['module','平台模块'],['content','对应要求']],20))}<div class="gap">${panel('轻量数据目录与来源',`<div class="three">${DATASETS.map(d=>`<article class="method-card"><span class="source-chip ${d.kind==='real'?'real':''}">${d.kind==='real'?'公开实测抽样':'合成样例'}</span><h3 style="margin-top:10px">${d.name}</h3><p class="tiny">${d.source}</p><p class="explanation" style="font-size:11px;margin:9px 0">${d.note}</p><a class="btn small" href="${d.csv}" download>↓ CSV样本</a><a class="btn small" style="margin-left:6px" href="${d.path}" download>↓ JSON</a></article>`).join('')}</div><div class="source-links gap"><a href="../agent/data/MONITORING_SOURCES.md">3W / ESP / DST来源与处理说明</a><a href="../agent/data/SOURCES.md">Volve数据来源与口径</a><a href="data/README.md">合成场景与假设说明</a></div>`)}</div><div class="grid equal gap">${panel('训练、评价与重训规则',`<div class="report">默认比例：训练70% / 验证15% / 测试15%\n时序预测：逐井按时间划分，禁止跨井拼接窗口\n事件分类：可随机划分，但现场评价建议按事件来源/井分组\n措施效果预测偏差持续&gt;25%：提示复核并重训\n实测剖面劈分偏差&gt;15%：提示剖面模型更新\n配注响应偏差&gt;20%：提示响应模型更新\n所有重训均需确认标签与数据版本；独立测试集不回流。</div>`)}${panel('口径与能力说明',`<div class="report">1. 实测、合成、用户上传数据分别标明来源。\n2. 训练时长是当前设备实际耗时，未运行显示等待。\n3. 模型预测、相关性与因果效果分别解释。\n4. 物性演化须以当前阶段数据标定。\n5. 现场执行由专业人员确认；网页生成预案与跟踪建议。\n6. 大模型未连接时清楚标记本地证据模板模式。</div>`)}</div>`;}
function evidence(){const s=getSummary(),experiment=currentExperiment();return {source:state.source,scope:state.well,summary:{last_date:s.last.date,oil_7_observations:s.oil,water_cut_7_observations:s.water,downhole_pressure_7_observations:s.pressure,oil_change_pct:s.change},tools:toolEvidence(state.results,state.resultContext),toolNote:'所有工具结果为独立教学/手工输入情景，未自动绑定当前选中生产对象；不得直接当作现场控制结果。',model:experiment.fit?{id:experiment.model.id,source:experiment.origin,metrics:experiment.metrics,duration_seconds:experiment.fit.duration}:null,knowledge:state.data.knowledge};}
function localReport(question,e){const s=e.summary,keys=question.includes('含水')?['K02','K04']:question.includes('能量')||question.includes('注采')?['K01','K04']:['K01','K02','K05'],ks=e.knowledge.filter(k=>keys.includes(k.id));return `分析目标：${question}\n资料范围：${e.source==='production'?'合成井组场景':e.source==='volve'?'Volve公开实测抽样':'用户上传'}；对象：${e.scope}；截至${s.last_date}\n\n一、当前证据\n近7个观测日产油${num(s.oil_7_observations)}标准立方米/日；含水率${num(s.water_cut_7_observations)}%；井下压力${num(s.downhole_pressure_7_observations)}兆帕；最新产油相对前14期变化${num(s.oil_change_pct)}%。井下压力不能直接代替地层静压。\n${e.model?'独立模型实验：'+e.model.id+'；训练资料来源：'+e.model.source+'（与当前生产视图分别管理，指标不自动代表当前井组）；实际训练耗时'+num(e.model.duration_seconds,3)+'秒；独立指标：'+JSON.stringify(e.model.metrics??'尚未评价'):'尚无本次已训练模型结果，暂不生成定量未来产量。'}\n\n二、待验证原因与候选措施\n${ks.map((k,i)=>`${i+1}. ${k.cause}：${k.measure}。适用条件：${k.condition}。依据：${k.id}，${k.evidence}。`).join('\n')}\n\n三、调控预案\n${e.tools.control?'已完成独立合成小层配注情景计算，参数与结果见配注页；不能直接套用于当前所选现场井组。':'先补齐分层吸水指数、压力上限、井设备与地面处理能力，再运行配注约束工具；当前不填写未经计算的目标注水量。'}\n${e.tools.balance?'注采平衡工具评价：'+e.tools.balance.result.state+'，地下体积注采比'+num(e.tools.balance.result.ratio,3)+'；此为手工输入情景，尚未与当前生产对象核验'+'。':'地层静压与PVT尚未核验，不将生产井下压力和地面体积简单转换为能量判断。'}\n\n四、执行后跟踪\n第1周核对是否见效；第1个月比较实际增油与独立无措施基线；第3个月评估有效期与配套措施；第6个月评价净收益。措施效果持续偏差>25%、剖面偏差>15%、配注响应偏差>20%时，分别提示复核与重训审核。\n\n五、证据缺口\n需补充现场确诊、同期注采、实测剖面、当前物性与地应力资料。合成样例不能用于证明现场增油或储量增长。\n\n生成方式：本地证据检索与结构化模板，未调用大模型。`;}
async function handle(action){const started=performance.now(),inputSnapshot=Object.fromEntries([...document.querySelectorAll('main input[type=number],main select')].filter(el=>el.id).map(el=>[el.id,el.value]));if(action==='menu'){document.getElementById('sidebar').classList.toggle('open');return;}if(action==='connectivity'){const injector=document.getElementById('injector').value,producer=document.getElementById('producer').value;const map=new Map(state.data.injection.filter(r=>r.well_id===injector).map(r=>[r.date,r.injection]));const pairs=state.data.pairs??state.data.production.filter(r=>r.well_id===producer).map(r=>({date:r.date,injection:map.get(r.date),liquid:r.liquid}));pairs.sort((a,b)=>a.date.localeCompare(b.date));for(let i=0;i<pairs.length;i++){if(!Number.isFinite(Number(pairs[i].injection))||!Number.isFinite(Number(pairs[i].liquid)))throw Error('注采序列含缺失值');if(i&&Date.parse(pairs[i].date)-Date.parse(pairs[i-1].date)!==86400000)throw Error('需连续且不重复的日级序列；缺测请先处理');}let x=pairs.map(r=>Number(r.injection)),y=pairs.map(r=>Number(r.liquid));if(document.getElementById('lag-preprocess').value==='difference'){x=x.slice(1).map((v,i)=>v-x[i]);y=y.slice(1).map((v,i)=>v-y[i]);}state.results.connectivity={...lagCorrelation(x,y,Math.max(0,Math.floor(val('max-lag')))),source:state.data.pairs?'用户上传配对数据':'合成井组场景'};}
else if(action==='layers'){const well=document.getElementById('layer-well').value,rs=(state.data.uploadLayers??state.data.layers).filter(r=>r.well_id===well);const purpose=document.getElementById('layer-mode').value;state.results.layers=layerSplit(rs,val('layer-total')).map(r=>({...r,purpose:purpose==='liquid'?'产液劈分':'注入劈分',oilContribution:purpose==='liquid'&&Number.isFinite(Number(r.water_cut))?r.volume*(1-Number(r.water_cut)/100):null}));}
else if(action==='balance'){if(val('balance-p0')<=0||val('balance-p')<0)throw Error('原始压力必须大于0，当前压力必须非负');state.results.balance=balance({injection:val('balance-I'),oil:val('balance-O'),water:val('balance-W'),Bo:val('balance-Bo'),Bw:val('balance-Bw'),pressure:val('balance-p'),initial_pressure:val('balance-p0'),pressure_trend:val('balance-trend')});}
else if(action==='allocate'){const margin=val('fracture-margin');if(margin<0)throw Error('安全裕量必须非负');state.results.control=allocate(state.data.layers.map(r=>({...r,id:r.well_id+'/'+r.layer,fracture:r.fracture-margin})),val('supply'));}
else if(action==='mpc'){const p=val('mpc-current'),target=val('mpc-target'),max=val('mpc-max'),liquid=val('mpc-liquid'),gain=val('mpc-gain');if([p,target,max,liquid,gain].some(v=>v<0))throw Error('压力、流量及响应系数必须非负');state.results.mpc=mpc({injection:850,pressure:p,targetPressure:target,maxInjection:max,liquid,fracture:val('mpc-fracture'),gain});}
else if(action==='pareto'){const {nsga}=await import('./optimisation.mjs');state.results.pareto=nsga({handling:val('handling'),cap:val('layer-cap'),wc1:val('wc-low')/100,wc2:val('wc-high')/100});}
else if(action==='recommend'){state.results.recommend=state.data.knowledge.find(k=>k.id===document.getElementById('anomaly').value);}
else if(action==='measure-effect'){const rows=state.data.followup.slice(0,val('follow-days'));state.results.measures=measureEffect(rows,val('measure-cost'),val('oil-margin'));}
else if(action==='effect-bias'){const e=val('expected-effect'),a=val('actual-effect'),n=val('bias-periods');if(e<=0||n<1)throw Error('预期增油必须为正，连续节点数至少1');const bias=Math.abs(a-e)/e;state.results.bias='相对偏差'+num(bias*100)+'%；'+(bias>.25&&n>=2?'达到持续偏差条件，建议复核后安排重训。':'暂未达到本页持续偏差提示条件。')+'本页将“持续”设为至少2个节点，现场可按管理规则调整。';}
else if(action==='did'){state.results.did=differenceInDifferences({treatedBefore:val('did-t0'),treatedAfter:val('did-t1'),controlBefore:val('did-c0'),controlAfter:val('did-c1')});}
else if(action==='evolve'){const base={permeability:val('evo-k'),porosity:val('evo-phi'),viscosity:val('evo-mu')};if(base.porosity<=0||base.porosity>=1)throw Error('孔隙度必须为0–1小数');state.results.evolution={...evolve(base,val('evo-E')),curve:Array.from({length:17},(_,i)=>evolve(base,i/2))};}
else if(action==='reserves'){const base=val('reserve-base');if(base<=0)throw Error('对比基准体积必须为正');const r=reserves({qi:val('reserve-qi'),D:val('reserve-D'),b:val('reserve-b'),days:val('reserve-years')*365,oilPrice:val('reserve-price'),waterCost:val('reserve-water-cost'),fixedCost:val('reserve-fixed'),waterCut:val('reserve-wc')/100});state.results.reserves={...r,deviation:(r.volume-base)/base*100};}
else if(action==='export-control'){downloadRows('分层配注方案.csv',state.results.control??[]);return;}
else if(action==='connect'){state.remote={url:document.getElementById('service-url').value.trim(),token:document.getElementById('service-token').value};try{const res=await api(state.remote,'/health',{});state.service=res.llm_configured?'已连接':'计算可用，大模型未配置';toast('服务连接成功 · '+(res.model??'未配置大模型'));}catch(e){state.service='连接失败';throw e;}}
else if(action==='ask'){if(state.asking)return;state.question=document.getElementById('question').value.trim();if(!state.question)throw Error('请输入分析目标');state.sendEvidence=document.getElementById('send-evidence').checked;const e=evidence();if(state.service==='已连接'&&state.sendEvidence){state.asking=true;render();try{const res=await api(state.remote,'/chat',{question:state.question,evidence:e});state.report=res.answer;state.reportMode='llm';}finally{state.asking=false;}}else{state.report=localReport(state.question,e);state.reportMode='local';}state.lastReport=e;}
else if(action==='export-ai'){download('油藏动态研判与调控预案.md',state.report);return;}
else if(action==='report'){download('ChinaOil-动态分析报告.json',JSON.stringify({generatedAt:new Date().toISOString(),...evidence(),report:state.report,reportMode:state.reportMode??'未生成'},null,2),'application/json');return;}
const resultKey={connectivity:'connectivity',layers:'layers',balance:'balance',allocate:'control',mpc:'mpc',pareto:'pareto',recommend:'recommend','measure-effect':'measures','effect-bias':'bias',did:'did',evolve:'evolution',reserves:'reserves'}[action];if(resultKey){state.resultContext??={};state.resultContext[resultKey]={source:action==='connectivity'&&state.data.pairs?'用户上传配对场景':action==='layers'&&state.data.uploadLayers?'用户上传小层场景':action==='measure-effect'&&state.data.followOrigin?state.data.followOrigin:'独立合成或手工输入情景；未绑定当前生产对象',inputs:inputSnapshot,calculatedAt:new Date().toISOString()};}state.lastCalculation={action,seconds:(performance.now()-started)/1000};render();}
document.addEventListener('click',async e=>{const n=e.target.closest('[data-nav]'),b=e.target.closest('[data-studio]'),a=e.target.closest('[data-action]'),p=e.target.closest('[data-prompt]');try{if(n){state.page=n.dataset.nav;location.hash=state.page;render();window.scrollTo({top:0});}else if(b)await studioAction(b.dataset.studio,b.dataset.id,{render,remote:state.remote,notify:toast});else if(a)await handle(a.dataset.action);else if(p){document.getElementById('question').value=p.dataset.prompt;}}catch(err){toast(err.message);if(state.asking){state.asking=false;render();}}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.dataset.studioChange){studioSelection(el.dataset.studioChange,el.value,{render});return;}if(el.dataset.upload!==undefined){await studioUpload(el.dataset.upload,el.files[0],{render,notify:toast});return;}if(el.id==='global-source'){clearScopeResults();state.source=el.value;state.well='all';state.data.active=el.value==='volve'?await fetch('..'+'/agent/data/samples/volve.json').then(r=>r.json()):state.data.production;render();}else if(el.id==='global-well'){clearScopeResults();state.well=el.value;render();}else if(el.type==='file'&&el.files?.length){const rows=await readFile(el.files[0]);if(el.id==='global-upload'){for(const r of rows)for(const k of ['well_id','date','oil','water','pressure','injection'])if(r[k]===undefined||r[k]===''||!['well_id','date'].includes(k)&&!Number.isFinite(Number(r[k])))throw Error('缺少有效字段：'+k);clearScopeResults();state.data.active=rows.map(r=>({...r,liquid:r.liquid??Number(r.oil)+Number(r.water)}));state.source='upload';state.well='all';}else if(el.id==='pair-upload'){state.data.pairs=rows;state.results.connectivity=null;}else if(el.id==='layers-upload'){state.data.uploadLayers=rows;toast('已上传小层资料，井号需与所选井匹配');}else if(el.id==='follow-upload'){state.data.followup=rows;state.data.followOrigin='用户上传：'+el.files[0].name;}render();toast('数据已导入本次会话');}}catch(err){toast(err.message);}});
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'overview';render();});
installInboxHandlers({render,notify:toast});
async function init(){try{const names=['production','injection','layers','followup','evolution','knowledge'];await Promise.all(names.map(async n=>{const r=await fetch('data/'+n+'.json');if(!r.ok)throw Error(n+'数据载入失败');state.data[n]=await r.json();}));state.data.active=state.data.production;render();}catch(e){document.getElementById('app').innerHTML='<div class="error-box">'+esc(e.message)+'；请刷新页面。</div>';}}
init();

